{"task": "Count events whose path contains at least one numeric resource id segment", "sql": "SELECT COUNT(*) FROM events WHERE regexp_like(path, '/[0-9]+(/|\\?|$)')"}
{"task": "List distinct paths with numeric ids under /api/v2/users for review", "sql": "SELECT DISTINCT path FROM events WHERE regexp_like(path, '^/api/v2/users/[0-9]+')"}
{"task": "Find events where the numeric id appears directly before the orders resource", "sql": "SELECT id, path FROM events WHERE regexp_like(path, '/users/[0-9]+/orders')"}
{"task": "Tag each event path as numeric-id, uuid-id, or other using a CASE expression", "sql": "SELECT id, path, CASE WHEN regexp_like(path, '/[0-9]+(/|\\?|$)') THEN 'numeric_id' WHEN regexp_like(path, '/[0-9a-fA-F-]{36}(/|\\?|$)') THEN 'uuid_id' ELSE 'other' END AS id_type FROM events"}
{"task": "Find failed requests (4xx/5xx) on paths containing a numeric resource id", "sql": "SELECT id, path, status FROM events WHERE status >= 400 AND regexp_like(path, '/[0-9]+(/|\\?|$)')"}
{"task": "Extract and count how many events hit each numeric order id under /orders/", "sql": "SELECT regexp_match(path, '/orders/([0-9]+)')[1] AS order_id, COUNT(*) AS hits FROM events WHERE regexp_like(path, '/orders/[0-9]+') GROUP BY order_id ORDER BY hits DESC"}
{"task": "Find log lines mentioning a request path with a numeric id followed by an error status code", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'path=/[^ ]*[0-9]+[^ ]*') AND regexp_like(message, 'status=(4|5)[0-9]{2}')"}
{"task": "Identify events whose numeric resource id is suspiciously large (6+ digits), possibly indicating an enumeration attack", "sql": "SELECT id, path FROM events WHERE regexp_like(path, '/[0-9]{6,}(/|\\?|$)')"}
{"task": "Compare request volume for numeric-id paths versus non-numeric (slug-based) paths per status code", "sql": "SELECT status, SUM(CASE WHEN regexp_like(path, '/[0-9]+(/|\\?|$)') THEN 1 ELSE 0 END) AS numeric_id_count, SUM(CASE WHEN NOT regexp_like(path, '/[0-9]+(/|\\?|$)') THEN 1 ELSE 0 END) AS other_count FROM events GROUP BY status"}
{"task": "Find error log entries that reference a numeric user id pattern like user/123 for correlation with events", "sql": "SELECT l.ts, l.level, l.service, l.message FROM logs l WHERE l.level = 'ERROR' AND regexp_like(l.message, 'user[/_]?[0-9]+', 'i')"}

